# Full read: every Computer Files registration dated Oct 2023 to Nov 2026, listed month by month under the type filter,
# and the full record of each one not yet on disk (raw files go to data/raw/full/, git-ignored). After this, a
# statement with no AI word (like "Code generated by Swift Assist in Xcode") can no longer hide from the count.
#   python code/fullread.py
import calendar, json, os, time, urllib.parse, urllib.request, concurrent.futures as cf
B = "https://api.publicrecords.copyright.gov/search_service_external/"
here = os.path.dirname(os.path.abspath(__file__)); D = os.path.join(here, "..", "data", "raw")
SAVE = os.path.join(D, "full"); os.makedirs(SAVE, exist_ok=True)
HAVE = set()
for d in (D, os.path.join(D, "baseline"), SAVE, os.path.join(here, "..", "..", "2026-11-11-copyright-ai-disclaimers", "data", "raw")):
    if os.path.isdir(d): HAVE |= {f[:-5] for f in os.listdir(d) if f.endswith(".json")}
def get(u):
    for k in range(6):
        try: return json.load(urllib.request.urlopen(urllib.request.Request(u, headers={"User-Agent": "curl/8.0"}), timeout=120))
        except Exception: time.sleep(2 + 2 * k)
def month(ym):
    y, m = map(int, ym.split("-")); end = f"{y}-{m:02d}-{calendar.monthrange(y, m)[1]:02d}"; out, p = [], 1
    while True:
        q = {"query": "*", "field_type": "keyword", "records_per_page": 100, "page_number": p, "type_of_work": "computer_file",
             "date_field": "registration_date_as_date", "start_date": f"{ym}-01 00:00:00", "end_date": f"{end} 23:59:59"}
        d = get(B + "simple_search_dsl?" + urllib.parse.urlencode(q))
        if d is None: print("FAILED", ym, p, flush=True); break
        h = d.get("data") or []; out += [x["hit"]["public_records_id"] for x in h]
        if len(h) < 100: break
        p += 1
    return ym, out
months = [f"{y}-{m:02d}" for y in (2023, 2024, 2025, 2026) for m in range(1, 13) if (2023, 10) <= (y, m) <= (2026, 11)]
listed = {}
with cf.ThreadPoolExecutor(4) as ex:
    for ym, ids in ex.map(month, months):
        listed[ym] = ids; print(ym, len(ids), flush=True)
json.dump(listed, open(os.path.join(here, "..", "data", "full_listing.json"), "w"))
todo = [i for ids in listed.values() for i in ids if i not in HAVE]
print("listed", sum(map(len, listed.values())), "to fetch", len(todo), flush=True)
def full(i):
    d = get(B + "search_unique_record?" + urllib.parse.urlencode({"query": i}))
    if d: json.dump(d, open(os.path.join(SAVE, i + ".json"), "w"))
n = 0
with cf.ThreadPoolExecutor(12) as ex:
    for _ in ex.map(full, todo):
        n += 1
        if n % 1000 == 0: print("full", n, flush=True)
print("done", flush=True)
